function solve(times, values, queries) {
  const n = Math.min(times.length, values.length);
  const entries = [];
  for (let i = 0; i < n; i++) entries.push([times[i], i, values[i]]);
  entries.sort((a, b) => (a[0] - b[0]) || (a[1] - b[1]));
  const ts = entries.map((e) => e[0]);
  const out = [];
  for (const q of queries) {
    let lo = 0;
    let hi = ts.length - 1;
    let pos = -1;
    while (lo <= hi) {
      const mid = (lo + hi) >> 1;
      if (ts[mid] <= q) {
        pos = mid;
        lo = mid + 1;
      } else {
        hi = mid - 1;
      }
    }
    out.push(pos === -1 ? -1 : entries[pos][2]);
  }
  return out;
}
